export function createNewSet(root,reset){const button=document.createElement('button');button.id='new-set';button.textContent='new set ↻';root.querySelector('.top-actions').insertBefore(button,root.querySelector('#done'));const dialog=document.createElement('dialog');dialog.id='new-set-confirm';dialog.setAttribute('aria-labelledby','new-set-title');dialog.innerHTML='<span id="new-set-title">START A NEW SET?</span><p>Your current design will be cleared.</p><div><button data-cancel>cancel</button><button data-start>start new</button></div>';root.append(dialog);button.onclick=()=>{dialog.showModal();dialog.querySelector('[data-cancel]').focus();};dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-start]').onclick=()=>{dialog.close();reset();};dialog.addEventListener('close',()=>button.focus());window.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();dialog.close();}else if(e.key==='Tab'){const controls=[...dialog.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.stopImmediatePropagation();}},true);return {close:()=>dialog.close()};}
